/**
 * i18n-messages.js — Haizakura WebUI 多语言文案表
 *
 * 纯 ES module，无外部依赖。被 i18n-core.js 导入，不需要单独 <script> 加载。
 *
 * 结构：
 *   { "zh-cn": { "nav.overview": "总览", ... }, "ja": {...}, "zh-pseudo": {...},
 *     "zh-tw": {...}, "en": {...} }
 *
 * 五个语言列**一一对应、key 完全一致**，新增条目必须五列同时补齐。
 *
 *   zh-cn      基准原文。与编译后 chunk 里写死的中文字面量逐字一致，
 *              i18n-dom.js 依赖这一列建立「中文原文 → key」的反向索引，
 *              **改动这一列的任何一个字都会让对应的 DOM 反向查找失效**。
 *   ja         标准日语（です・ます / である 混用，UI 惯例）。
 *   zh-pseudo  伪中国语：全汉字、无假名，配日语文言语法（〜也 / 〜之 / 〜者 / 〜為）。
 *   zh-tw      繁體中文，台湾用词（檔案 / 資料 / 登入 / 設定 / 網路 / 伺服器 …）。
 *   en         English。
 *
 * 文案覆盖 7 个页面：总览 / 进程 / 日志 / 调试 / 配置 / 设置 / 文档，
 * 外加登录与首次引导、2FA、通知、存储、更新、外观主题等常见 UI。
 *
 * 本文件由构建脚本生成，请勿手工调整缩进；新增条目追加到对应语言块末尾即可。
 */

