/** 文案表里实际存在的语言码（顺序与内容块一致）。 */
export const MESSAGE_LANGS = ["zh-cn","ja","zh-pseudo","zh-tw","en"];

/** key 清单（以 zh-cn 基准列为准）。供调试与覆盖率统计使用。 */
export const MESSAGE_KEYS = Object.freeze(Object.keys(MESSAGES["zh-cn"]));

export default MESSAGES;
